/// Shadow tokens. Light: soft shadows. Dark: no card shadow — `card` is a 1px `line` ring.
/// Read with `context.elevation.card` / `.float`.
@immutable
class AppElevation extends ThemeExtension<AppElevation> {
  const AppElevation({required this.card, required this.float});

  /// `shadow-card` — Cards and list groups at rest (dark: a 1px line ring).
  final List<BoxShadow> card;

  /// `shadow-float` — FAB, bottom sheet, toasts.
  final List<BoxShadow> float;

  static const light = AppElevation(
    card: [
      BoxShadow(
        color: Color(0x0A101618),
        offset: Offset(0, 1),
        blurRadius: 2,
        spreadRadius: 0,
      ),
      BoxShadow(
        color: Color(0x0D101618),
        offset: Offset(0, 1),
        blurRadius: 3,
        spreadRadius: 0,
      ),
    ],
    float: [
      BoxShadow(
        color: Color(0x29101618),
        offset: Offset(0, 6),
        blurRadius: 16,
        spreadRadius: -2,
      ),
      BoxShadow(
        color: Color(0x1A101618),
        offset: Offset(0, 2),
        blurRadius: 4,
        spreadRadius: 0,
      ),
    ],
  );

  static const dark = AppElevation(
    card: [
      BoxShadow(
        color: Color(0xFF2A3236),
        offset: Offset(0, 0),
        blurRadius: 0,
        spreadRadius: 1,
      ),
    ],
    float: [
      BoxShadow(
        color: Color(0xCC000000),
        offset: Offset(0, 10),
        blurRadius: 28,
        spreadRadius: -4,
      ),
    ],
  );

  @override
  AppElevation copyWith({List<BoxShadow>? card, List<BoxShadow>? float}) =>
      AppElevation(card: card ?? this.card, float: float ?? this.float);

  @override
  AppElevation lerp(covariant ThemeExtension<AppElevation>? other, double t) =>
      other is AppElevation && t >= 0.5 ? other : this;
}

/// Type scale on Be Vietnam Pro (no colour — text inherits `ink` from the theme).
/// Money: add `.tabular` (see app_theme.dart) — the bundled TTFs carry a `tnum` feature.
abstract final class AppType {
  static const fontFamily = 'BeVietnamPro';

  /// `display` 40/48 w700 — The total-spend hero on Overview, and Calendar's month total. Always tabular figures.
  static const display = TextStyle(
    fontFamily: fontFamily,
    fontSize: 40,
    height: 48 / 40,
    fontWeight: FontWeight.w700,
    letterSpacing: -0.8,
  );

  /// `amount-lg` 34/40 w600 — Editable amounts: the price in the form, the amount in the confirm sheet.
  static const amountLg = TextStyle(
    fontFamily: fontFamily,
    fontSize: 34,
    height: 40 / 34,
    fontWeight: FontWeight.w600,
    letterSpacing: -0.51,
  );

  /// `headline` 28/34 w700 — Large screen titles (Overview, Insights).
  static const headline = TextStyle(
    fontFamily: fontFamily,
    fontSize: 28,
    height: 34 / 28,
    fontWeight: FontWeight.w700,
    letterSpacing: -0.28,
  );

  /// `title` 20/26 w600 — Sheet titles, top-bar titles, section headings.
  static const title = TextStyle(
    fontFamily: fontFamily,
    fontSize: 20,
    height: 26 / 20,
    fontWeight: FontWeight.w600,
    letterSpacing: -0.1,
  );

  /// `title-sm` 16/22 w600 — Row and card titles; row amounts (tabular).
  static const titleSm = TextStyle(
    fontFamily: fontFamily,
    fontSize: 16,
    height: 22 / 16,
    fontWeight: FontWeight.w600,
    letterSpacing: 0,
  );

  /// `body` 15/22 w400 — Default text, card copy, field values.
  static const body = TextStyle(
    fontFamily: fontFamily,
    fontSize: 15,
    height: 22 / 15,
    fontWeight: FontWeight.w400,
    letterSpacing: 0,
  );

  /// `label` 14/20 w600 — Buttons, chips, segmented control, tab-free labels.
  static const label = TextStyle(
    fontFamily: fontFamily,
    fontSize: 14,
    height: 20 / 14,
    fontWeight: FontWeight.w600,
    letterSpacing: 0,
