  /// `caption` 12/16 w600 — Section eyebrows (uppercase), badges, tab-bar labels (11–12px).
  static const caption = TextStyle(
    fontFamily: fontFamily,
    fontSize: 12,
    height: 16 / 12,
    fontWeight: FontWeight.w600,
    letterSpacing: 0.24,
  );
}

/// 4/8 grid. Screen gutter is space-4 (16px) so 360-wide Android fits.
abstract final class AppSpace {
  /// `space-1` — Icon-to-label gap, badge padding.
  static const double s1 = 4;

  /// `space-2` — Between chips; inside compact controls.
  static const double s2 = 8;

  /// `space-3` — Tile-to-text gap in rows; between stacked cards.
  static const double s3 = 12;

  /// `space-4` — Screen gutter, card padding, row padding.
  static const double s4 = 16;

  /// `space-5` — Sheet padding.
  static const double s5 = 20;

  /// `space-6` — Between sections.
  static const double s6 = 24;

  /// `space-8` — Hero top/bottom breathing room.
  static const double s8 = 32;

  /// `space-10` — Empty-state illustration margins.
  static const double s10 = 40;
}

/// Soft and friendly; tiles scale their radius with size (≈ 0.27 × side).
abstract final class AppRadius {
  /// `radius-tile-24` — 24px tile (calendar, stacked avatars).
  static const double tile24 = 7;

  /// `radius-tile-40` — 40px tile (list rows).
  static const double tile40 = 11;

  /// `radius-tile-56` — 56px tile (form header, sheet).
  static const double tile56 = 15;

  /// `radius-tile-80` — 80px tile (detail hero).
  static const double tile80 = 22;

  /// `radius-sm` — Segmented-control thumb, small inputs.
  static const double sm = 8;

  /// `radius-md` — Inputs, buttons, inner panels.
  static const double md = 12;

  /// `radius-lg` — Cards and list groups.
  static const double lg = 16;

  /// `radius-xl` — Bottom-sheet top corners.
  static const double xl = 28;

  /// `radius-full` — Chips, badges, FAB, toggle, pill indicators.
  static const double full = 9999;
}

/// Touch targets and fixed component heights.
abstract final class AppSize {
  /// `tap-min` — Minimum touch target on every control.
  static const double tapMin = 44;

  /// `row-h` — Subscription row height (40px tile + 2 lines).
  static const double rowH = 68;

  /// `button-h` — Primary / secondary buttons.
  static const double buttonH = 52;

  /// `fab-size` — Floating add button.
  static const double fabSize = 56;

  /// `tabbar-h` — Tab bar, excluding the home-indicator inset.
  static const double tabbarH = 64;
}
